 private void updateClock(){long now=System.currentTimeMillis();java.util.TimeZone zone=java.util.TimeZone.getDefault();String key=now/60000+":"+zone.getID()+":"+zone.getOffset(now)+":"+android.text.format.DateFormat.is24HourFormat(this);if(key.equals(clockKey))return;clockKey=key;java.util.Date date=new java.util.Date(now);java.text.DateFormat time=android.text.format.DateFormat.getTimeFormat(this);time.setTimeZone(zone);java.text.DateFormat day=java.text.DateFormat.getDateInstance(java.text.DateFormat.MEDIUM);day.setTimeZone(zone);String weekday=new java.text.SimpleDateFormat("EEE",java.util.Locale.getDefault()).format(date);clockLabel.setText(time.format(date)+" · "+new java.text.SimpleDateFormat("EEE d MMM",java.util.Locale.getDefault()).format(date)+" · "+PetState.dayPhase(PetState.localMinute(now,zone)));}
 private void routine(){PetState s=state();dialog().setTitle("Real-time routine").setMessage("Synced to your phone's clock and time zone.\nBedtime: 9 PM • Wake up: 7 AM\nSleeping restores energy and pauses hunger, happiness and care penalties. You can wake your pet for 15 minutes if needed.").setPositiveButton(s.autoSleep?"Disable auto sleep":"Enable auto sleep",(d,i)->act(25,0)).setNeutralButton(s.sleeping()?"Wake briefly":"Nap",(d,i)->act(16,0)).setNegativeButton("Close",null).show();}
 private boolean onPet(MotionEvent e){float z=Math.min(scene.getWidth()/160f,scene.getHeight()/192f);if(z<=0)return false;float x=(e.getX()-(scene.getWidth()-160*z)/2)/z,y=(e.getY()-(scene.getHeight()-192*z)/2)/z;return x>30&&x<130&&y>55&&y<165;}
 private void button(LinearLayout row,String label,Runnable run){Button b=new Button(this);b.setAllCaps(false);b.setText(label);b.setTextSize(13);String symbol=label.equals("Feed")?"●":label.equals("Care")?"♥":label.equals("Arcade")?"✦":label.equals("Lab")?"▦":label.equals("Journal")?"▤":label.equals("World")?"◉":"";if(!symbol.isEmpty()){b.setText(symbol+"  "+label);b.setContentDescription(label);}b.setTypeface(Typeface.create("sans-serif-medium",0));b.setTextColor(0xfff8edff);b.setMinWidth(0);b.setMinHeight(0);b.setPadding(dp(4),0,dp(4),0);android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0xff353b60,0xff292e4b});bg.setCornerRadius(dp(13));bg.setStroke(dp(1),0xff575d83);b.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x55816bdb),bg,null));b.setElevation(0);b.setOnClickListener(v->run.run());LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(48),1);lp.setMargins(dp(3),dp(4),dp(3),dp(4));row.addView(b,lp);}
 private void lab(){dialog().setTitle("FOREVER LAB").setItems(new String[]{"Shop","Inventory","Creature collection","Space travel"},(d,i)->{if(i==0)shop(false);else if(i==1)shop(true);else if(i==2){PetState p=pet.snapshot();StringBuilder b=new StringBuilder();for(int n=0;n<PetState.SPECIES.length;n++)b.append((p.collection&(1<<n))!=0?PetState.SPECIES[n]:"????").append("\n");collection(p);}else{PetState p=pet.snapshot();dialog().setTitle("Space travel").setMessage("Biofuel: "+p.fuel+"/4").setPositiveButton("Launch",(x,y)->{if(pet.snapshot().fuel<4){Toast.makeText(this,"Collect 4 biofuel first",0).show();return;}act(12,0);zoom=0;rebuild();}).setNegativeButton("Cancel",null).show();}}).show();}
 private void collection(PetState p){ScrollView scroll=new ScrollView(this);LinearLayout grid=new LinearLayout(this);grid.setOrientation(1);grid.setBackgroundColor(0xff242447);scroll.addView(grid);for(int i=0;i<PetState.SPECIES.length;i+=3){LinearLayout row=new LinearLayout(this);grid.addView(row);for(int j=i;j<i+3;j++){PetState preview=new PetState();preview.stage=4;preview.field=(j%12)/4;preview.body=j%4;preview.variant=j/12;boolean found=(p.collection&(1<<j))!=0;LinearLayout tile=new LinearLayout(this);tile.setOrientation(1);tile.setGravity(17);tile.setPadding(dp(4),dp(8),dp(4),dp(8));ImageView im=new ImageView(this);im.setImageBitmap(found?art.creatureIcon(preview):art.silhouette(preview));tile.addView(im,new LinearLayout.LayoutParams(dp(64),dp(64)));TextView label=new TextView(this);label.setGravity(Gravity.CENTER);label.setText(found?PetState.SPECIES[j]:"???");label.setTextColor(0xfff6eaff);label.setTextSize(11);tile.addView(label);row.addView(tile,new LinearLayout.LayoutParams(0,-2,1));}}dialog().setTitle("Creature collection • "+Integer.bitCount(p.collection)+"/"+PetState.SPECIES.length).setView(scroll).setPositiveButton("Close",null).show();}
 private void shop(boolean bag){PetState p=pet.snapshot();LinearLayout list=new LinearLayout(this);list.setOrientation(1);list.setPadding(dp(12),dp(8),dp(12),dp(8));list.setBackgroundColor(0xff242447);ScrollView sc=new ScrollView(this);sc.addView(list);AlertDialog dlg=dialog().setTitle(bag?"Inventory":"Shop • "+p.coins+" coins").setView(sc).setNegativeButton("Close",null).create();
 for(int i=0;i<PetState.ITEMS.length;i++){final int item=i;boolean own=(p.owned&(1<<i))!=0;if(bag&&!own)continue;LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(6),dp(4),dp(6),dp(4));ImageView icon=new ImageView(this);icon.setImageBitmap(art.itemIcon(i));icon.setScaleType(ImageView.ScaleType.FIT_CENTER);row.addView(icon,new LinearLayout.LayoutParams(dp(52),dp(52)));TextView name=new TextView(this);name.setText(PetState.ITEMS[i]+"\n"+(own?"Owned":PetState.PRICES[i]+" coins"));name.setTextColor(0xfff8edff);name.setTextSize(14);row.addView(name,new LinearLayout.LayoutParams(0,-2,1));Button buy=new Button(this);buy.setText(bag?(p.equipped==i+1||p.installation==i+1?"Active":"Use"):own?"Owned":"Buy");buy.setEnabled(bag||!own);buy.setOnClickListener(v->{if(!bag&&pet.snapshot().coins<PetState.PRICES[item]){Toast.makeText(this,"Not enough coins",0).show();return;}act(bag?11:10,item);dlg.dismiss();shop(bag);});row.addView(buy,new LinearLayout.LayoutParams(dp(76),dp(48)));list.addView(row);}
 if(bag&&p.owned==0){TextView empty=new TextView(this);empty.setText("Your bag is empty. Visit the shop.");empty.setTextColor(0xfff8edff);list.addView(empty);}dlg.show();}
